sealed class ChartException: kotlin.Exception() {
    
    class InvalidLane(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class InvalidHold(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class OutsideDuration(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class NotSorted(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class SameLaneOverlap(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class InvalidTime(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class BeforeCoverage(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    
    class HoldEndWithoutStart(
        
        val `lane`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "lane=${ `lane` }"
    }
    
    class UnclosedHold(
        
        val `object`: kotlin.UInt
        ) : ChartException() {
        override val message
            get() = "object=${ `object` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ChartException> {
        override fun lift(error_buf: RustBuffer.ByValue): ChartException = FfiConverterTypeChartError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeChartError : FfiConverterRustBuffer<ChartException> {
    override fun read(buf: ByteBuffer): ChartException {
        

        return when(buf.getInt()) {
            1 -> ChartException.InvalidLane(
                FfiConverterUInt.read(buf),
                )
            2 -> ChartException.InvalidHold(
                FfiConverterUInt.read(buf),
                )
            3 -> ChartException.OutsideDuration(
                FfiConverterUInt.read(buf),
                )
            4 -> ChartException.NotSorted(
                FfiConverterUInt.read(buf),
                )
            5 -> ChartException.SameLaneOverlap(
                FfiConverterUInt.read(buf),
                )
            6 -> ChartException.InvalidTime(
                FfiConverterUInt.read(buf),
                )
            7 -> ChartException.BeforeCoverage(
                FfiConverterUInt.read(buf),
                )
            8 -> ChartException.HoldEndWithoutStart(
                FfiConverterUInt.read(buf),
                )
            9 -> ChartException.UnclosedHold(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ChartException): ULong {
        return when(value) {
            is ChartException.InvalidLane -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.InvalidHold -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.OutsideDuration -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.NotSorted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.SameLaneOverlap -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.InvalidTime -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.BeforeCoverage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
            is ChartException.HoldEndWithoutStart -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`lane`)
            )
            is ChartException.UnclosedHold -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`object`)
            )
        }
    }

    override fun write(value: ChartException, buf: ByteBuffer) {
        when(value) {
            is ChartException.InvalidLane -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.InvalidHold -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.OutsideDuration -> {
                buf.putInt(3)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.NotSorted -> {
                buf.putInt(4)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.SameLaneOverlap -> {
                buf.putInt(5)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.InvalidTime -> {
                buf.putInt(6)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.BeforeCoverage -> {
                buf.putInt(7)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
            is ChartException.HoldEndWithoutStart -> {
                buf.putInt(8)
                FfiConverterUInt.write(value.`lane`, buf)
                Unit
            }
            is ChartException.UnclosedHold -> {
                buf.putInt(9)
                FfiConverterUInt.write(value.`object`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class ControlStatus {
    
    /**
     * Checked against human judgement.
     */
    WORKS,
    /**
     * Accepted and measured, but not checked against human judgement.
     */
    EXPERIMENTAL,
    /**
     * Accepted but known not to do what it says; not to be offered.
     */
    NOT_WORKING;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeControlStatus: FfiConverterRustBuffer<ControlStatus> {
    override fun read(buf: ByteBuffer) = try {
        ControlStatus.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ControlStatus) = 4UL

    override fun write(value: ControlStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





