sealed class GeneratorException: kotlin.Exception() {
    
    /**
     * A file of the model directory or a resampler table is missing or unreadable, the directory holds
     * a model this runtime does not run, or a package manifest (`ensomi-package.json`) is refused.
     */
    class Model(
        
        val `messageText`: kotlin.String
        ) : GeneratorException() {
        override val message
            get() = "message=${ `messageText` }"
    }
    
    /**
     * The generation was refused or failed. `code` is EnsomiProtocol's `ErrorEvent.code`:
     * `star_out_of_range`, `unsupported_control` or `generation_failed`.
     */
    class Generation(
        
        val `code`: kotlin.String, 
        
        val `messageText`: kotlin.String
        ) : GeneratorException() {
        override val message
            get() = "code=${ `code` }, message=${ `messageText` }"
    }
    
    /**
     * Stopped through its `Cancellation`.
     */
    class Cancelled(
        ) : GeneratorException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<GeneratorException> {
        override fun lift(error_buf: RustBuffer.ByValue): GeneratorException = FfiConverterTypeGeneratorError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeGeneratorError : FfiConverterRustBuffer<GeneratorException> {
    override fun read(buf: ByteBuffer): GeneratorException {
        

        return when(buf.getInt()) {
            1 -> GeneratorException.Model(
                FfiConverterString.read(buf),
                )
            2 -> GeneratorException.Generation(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> GeneratorException.Cancelled()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GeneratorException): ULong {
        return when(value) {
            is GeneratorException.Model -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is GeneratorException.Generation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`message`)
            )
            is GeneratorException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: GeneratorException, buf: ByteBuffer) {
        when(value) {
            is GeneratorException.Model -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is GeneratorException.Generation -> {
                buf.putInt(2)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is GeneratorException.Cancelled -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



