            get() = "keys=${ `keys` }"
    }
    
    class UnsupportedHitObject(
        
        val `line`: kotlin.String
        ) : OsuException() {
        override val message
            get() = "line=${ `line` }"
    }
    
    class InvalidChart(
        
        val `error`: ChartException
        ) : OsuException() {
        override val message
            get() = "error=${ `error` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<OsuException> {
        override fun lift(error_buf: RustBuffer.ByValue): OsuException = FfiConverterTypeOsuError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeOsuError : FfiConverterRustBuffer<OsuException> {
    override fun read(buf: ByteBuffer): OsuException {
        

        return when(buf.getInt()) {
            1 -> OsuException.UnsupportedMode()
            2 -> OsuException.UnsupportedKeyCount(
                FfiConverterLong.read(buf),
                )
            3 -> OsuException.UnsupportedHitObject(
                FfiConverterString.read(buf),
                )
            4 -> OsuException.InvalidChart(
                FfiConverterTypeChartError.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: OsuException): ULong {
        return when(value) {
            is OsuException.UnsupportedMode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is OsuException.UnsupportedKeyCount -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`keys`)
            )
            is OsuException.UnsupportedHitObject -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`line`)
            )
            is OsuException.InvalidChart -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeChartError.allocationSize(value.`error`)
            )
        }
    }

    override fun write(value: OsuException, buf: ByteBuffer) {
        when(value) {
            is OsuException.UnsupportedMode -> {
                buf.putInt(1)
                Unit
            }
            is OsuException.UnsupportedKeyCount -> {
                buf.putInt(2)
                FfiConverterLong.write(value.`keys`, buf)
                Unit
            }
            is OsuException.UnsupportedHitObject -> {
                buf.putInt(3)
                FfiConverterString.write(value.`line`, buf)
                Unit
            }
            is OsuException.InvalidChart -> {
                buf.putInt(4)
                FfiConverterTypeChartError.write(value.`error`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




